```javascript
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createFooterColophon(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const group = new Group();
  const WIDTH = 6.8;
  const HEIGHT = 2.0;

  // Colors from spec
  const colors = config.intent?.visualSpec?.colors || {
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  function hexToRgb(hex) {
    return {
      r: parseInt(hex.slice(1, 3), 16) / 255,
      g: parseInt(hex.slice(3, 5), 16) / 255,
      b: parseInt(hex.slice(5, 7), 16) / 255
    };
  }

  // ===== BACKGROUND PLANE WITH GRADIENT =====
  const bgGeom = new PlaneGeometry(WIDTH, HEIGHT);
  const bottomColor = hexToRgb('#0b0b10');
  const topColor = hexToRgb('#121218');

  const bgMat = new MeshStandardNodeMaterial({
    colorNode: mix(
      vec3(bottomColor.r, bottomColor.g, bottomColor.b),
      vec3(topColor.r, topColor.g, topColor.b),
      uv().y
    ),
    roughness: 0.6,
    metalness: 0.2
  });

  const bgPlane = new Mesh(bgGeom, bgMat);
  group.add(bgPlane);

  // ===== WORDMARK =====
  const wordmarkText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.68
  });
  wordmarkText.position.set(-WIDTH / 2 + 0.5, 0.5, 0.01);
  group.add(wordmarkText);

  // ===== ACCENT BAR =====
  const accentGeom = new PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.4
  });
  const accentBar = new Mesh(accentGeom, accentMat);
  accentBar.position.set(-WIDTH / 2 + 0.5, 0.15, 0.01);
  group.add(accentBar);

  // ===== COLUMNS =====
  const columns = [
    { header: 'ATELIER', links: ['Features', 'Collection', 'Pricing'] },
    { header: 'COMPANY', links: ['Journal', 'Visit the Atelier', 'Contact'] },
    { header: 'LEGAL', links: ['Privacy', 'Terms', 'Warranty'] }
  ];

  let colX = -WIDTH / 2 + 2.575;

  columns.forEach((col) => {
    // Column header
    const headerText = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 1.08
    });
    headerText.position.set(colX, 0.4, 0.01);
    group.add(headerText);

    // Links
    col.links.forEach((linkName, idx) => {
      const linkText = ctx.fontAtlas.createText(linkName, {
        fontSize: 13,
        color: colors.paper,
        align: 'left'
      });

      const linkY = 0.1 - idx * 0.2;
      linkText.position.set(colX, linkY, 0.01);

      const linkGroup = new Group();
      linkGroup.add(linkText);

      const accentRgb = hexToRgb(colors.accent);
      const paperRgb = hexToRgb(colors.paper);

      linkGroup.userData.handlers = {
        hover: () => {
          gsap.to(linkText.position, {
            z: 0.02,
            duration: 0.14,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });

          linkText.traverse(child => {
            if (child.material && child.material.color) {
              gsap.to(child.material.color, {
                r: accentRgb.r,
                g: accentRgb.g,
                b: accentRgb.b,
                duration: 0.14,
                ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
                onUpdate: () => {
                  if (child.material) child.material.needsUpdate = true;
                }
              });
            }
          });
        },
        unhover: () => {
          gsap.to(linkText.position, {
            z: 0.01,
            duration: 0.14,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });

          linkText.traverse(child => {
            if (child.material && child.material.color) {
              gsap.to(child.material.color, {
                r: paperRgb.r,
                g: paperRgb.g,
                b: paperRgb.b,
                duration: 0.14,
                ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
                onUpdate: () => {
                  if (child.material) child.material.needsUpdate = true;
                }
              });
            }
          });
        }
      };

      group.add(linkGroup);
    });

    colX += 1.575;
  });

  // ===== HAIRLINE RULES =====
  const hairlineGeom = new PlaneGeometry(WIDTH, 0.006);
  const hairlineMat = new MeshBasicNodeMaterial({ color: 0x23232b });

  const hairlineTop = new Mesh(hairlineGeom, hairlineMat);
  hairlineTop.position.y = HEIGHT / 2;
  hairlineTop.position.z = 0.01;
  group.add(hairlineTop);

  const hairlineBottom = new Mesh(hairlineGeom, hairlineMat);
  hairlineBottom.position.y = -HEIGHT / 2 + 0.625;
  hairlineBottom.position.z = 0.01;
  group.add(hairlineBottom);

  // ===== LEGAL TEXT =====
  const legalText = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 0.36
    }
  );
  legalText.position.set(0, -HEIGHT / 2 + 0.2, 0.01);
  group.add(legalText);

  // ===== ENTRANCE ANIMATION =====
  group.position.y = 0.2;

  const allMaterials = [];
  group.traverse(node => {
    if (node.material) {
      node.material.transparent = true;
      node.material.opacity = 0;
      allMaterials.push(node.material);
    }
  });

  const timeline = gsap.timeline();

  timeline.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  }, 0);

  allMaterials.forEach(mat => {
    timeline.to(mat, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
  });

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timeline.kill();
    gsap.killTweensOf(allMaterials);
    group.traverse(node => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach(m => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return group;
}
